        void ScriptA4Rin::a4_rin() {
            if (ks::globals::exit_scenario) return;
            SKIP_IF_LOAD_ANOTHER_SCENE(SCRIPT_A4_RIN);
            ks::SceneManager::set_script(SCRIPT_A4_RIN);
            ks::SceneManager::init_savedata(ks::progress);
            ks::SceneManager::set(ks::SceneManager("script_a4_rin"));
        
            ScriptA4Rin::a4_rin_illusions_for_people(); // INLINE CALL
            ks::SceneManager::timeskip();
            ScriptA4Rin::a4_rin_demused(); // INLINE CALL
            ks::SceneManager::timeskip();
            ScriptA4Rin::a4_rin_the_scene(); // INLINE CALL
            ks::SceneManager::timeskip();
            if (ks::progress.is_true) {
                ScriptA4Rin::a4_rin_wavelength(); // INLINE CALL
                ks::SceneManager::timeskip();
                ScriptA4Rin::a4_rin_blue_period(); // INLINE CALL
                ScriptA4Rin::a4_rin_the_world_only_can_you_see(); // INLINE CALL
            } else {
                ScriptA4Rin::a4_rin_desperate_glory(); // INLINE CALL
                ScriptA4Rin::a4_rin_problems_of_self_referential_logic(); // INLINE CALL
                ScriptA4Rin::a4_rin_measuring_shadows(); // INLINE CALL
                ScriptA4Rin::a4_rin_raison_detre(); // INLINE CALL
                ks::SceneManager::timeskip();
                ScriptA4Rin::a4_rin_wb_and_ws(); // INLINE CALL
                ScriptA4Rin::a4_rin_proof_of_existence(); // INLINE CALL
            }
        }
